// Differential checks of ReadBeforeWrite-pbo.js against Lean, generated by leanscript --check
import * as M from "./ReadBeforeWrite-pbo.js";

function show(v) {
  if (Array.isArray(v) || ArrayBuffer.isView(v)) return "#[" + [...v].map(show).join(", ") + "]";
  // a list of cons cells (`ListRepr.taggedUnion`) is shown as its elements
  if (v !== null && typeof v === "object" && (v.tag === 0 || v.tag === 1)) {
    const a = [];
    for (; v.tag === 1; v = v._2) a.push(v._1);
    return show(a);
  }
  return String(v);
}
function floatBits(x) {
  return String(new BigUint64Array(new Float64Array([x]).buffer)[0]);
}
function isNaNBits(s) {
  const b = BigInt(s);
  return ((b >> 52n) & 0x7ffn) === 0x7ffn && (b & 0xfffffffffffffn) !== 0n;
}
let passed = 0, failed = 0;
function check(label, thunk, expected, isFloat) {
  let got;
  try {
    const v = thunk();
    got = isFloat ? floatBits(v) : show(v);
    // NaN payloads differ between platforms: any NaN matches any NaN
    if (isFloat && Number.isNaN(v) && isNaNBits(expected)) got = expected;
  } catch (e) {
    got = "threw: " + e.message;
  }
  if (got === expected) passed++;
  else {
    failed++;
    console.log(`FAIL ${label}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(got)}`);
  }
}

check("test1(0)", () => M.test1(0), "14", false);
check("test1(1)", () => M.test1(1), "16", false);
check("test1(2)", () => M.test1(2), "18", false);
check("test1(5)", () => M.test1(5), "24", false);
check("test1(13)", () => M.test1(13), "40", false);
check("test2(0)", () => M.test2(0), "13", false);
check("test2(1)", () => M.test2(1), "24", false);
check("test2(2)", () => M.test2(2), "35", false);
check("test2(5)", () => M.test2(5), "68", false);
check("test2(13)", () => M.test2(13), "156", false);
check("test3(0)", () => M.test3(0), "3", false);
check("test3(1)", () => M.test3(1), "4", false);
check("test3(2)", () => M.test3(2), "5", false);
check("test3(5)", () => M.test3(5), "8", false);
check("test3(13)", () => M.test3(13), "16", false);
check("test5(0)", () => M.test5(0), "0", false);
check("test5(1)", () => M.test5(1), "4", false);
check("test5(2)", () => M.test5(2), "8", false);
check("test5(5)", () => M.test5(5), "20", false);
check("test5(13)", () => M.test5(13), "52", false);

console.log(`ReadBeforeWrite-pbo.js: ${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);
